#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const inputPath = path.join(root, 'design-system', 'nova-design-tokens.json');
const tokens = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
const checkOnly = process.argv.includes('--check');
const qml = generateQml(tokens)
  .replace(
    'property real densityScale: 1.0',
    `property real densityScale: 1.0\n    property int radiusBase: ${tokens.desktopRadiusBase}`,
  )
  .replace(
    `readonly property int radiusSmall: ${tokens.radiusDp.extraSmall}\n    readonly property int radiusMedium: ${tokens.radiusDp.small}\n    readonly property int radiusLarge: ${tokens.radiusDp.medium}`,
    `readonly property int radiusSmall: Math.max(3, Math.round(radiusBase * ${tokens.radiusDp.extraSmall / tokens.desktopRadiusBase}))\n    readonly property int radiusMedium: Math.max(5, Math.round(radiusBase * ${tokens.radiusDp.small / tokens.desktopRadiusBase}))\n    readonly property int radiusLarge: Math.max(8, Math.round(radiusBase * ${tokens.radiusDp.medium / tokens.desktopRadiusBase}))`,
  );

if (tokens.schemaVersion !== 1) {
  throw new Error(`Unsupported NOVA design token schema: ${tokens.schemaVersion}`);
}
for (const [paletteName, palette] of Object.entries(tokens.palettes ?? {})) {
  for (const [tokenName, color] of Object.entries(palette)) {
    if (!/^#[0-9a-fA-F]{6}$/.test(color)) {
      throw new Error(`Invalid color token ${paletteName}.${tokenName}: ${color}`);
    }
  }
}
for (const paletteName of ['light', 'dark', 'highContrastLight', 'highContrastDark']) {
  if (!tokens.palettes?.[paletteName]) {
    throw new Error(`Missing required color palette: ${paletteName}`);
  }
}

const outputs = new Map([
  [path.join(root, 'desktop-native', 'qml', 'Theme.qml'), qml],
  [
    path.join(root, 'android', 'app', 'src', 'main', 'java', 'com', 'nova', 'downloadmanager', 'design', 'NovaDesignTokens.generated.kt'),
    generateKotlin(tokens),
  ],
]);

let stale = false;
for (const [outputPath, contents] of outputs) {
  const current = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : null;
  if (current === contents) continue;
  if (checkOnly) {
    console.error(`generated design token file is stale: ${path.relative(root, outputPath)}`);
    stale = true;
  } else {
    fs.writeFileSync(outputPath, contents, 'utf8');
    console.log(`generated ${path.relative(root, outputPath)}`);
  }
}

if (stale) process.exitCode = 1;

function generateQml(source) {
  const p = source.palettes;
  const layout = source.desktopLayoutPx;
  const colors = (name) => p[name];
  return `// Generated by scripts/generate-design-tokens.mjs from nova-design-tokens.json.\npragma Singleton\n\nimport QtQuick\n\nQtObject {\n    property bool darkMode: true\n    property bool highContrast: false\n    property bool reducedMotion: false\n    property real fontScale: 1.0\n    property color accentBase: \"${source.brand.accent}\"\n    property real densityScale: 1.0\n\n    readonly property color window: highContrast ? (darkMode ? "${colors('highContrastDark').window}" : "${colors('highContrastLight').window}") : (darkMode ? "${colors('dark').window}" : "${colors('light').window}")\n    readonly property color sidebar: highContrast ? (darkMode ? \"${colors('highContrastDark').sidebar}\" : \"${colors('highContrastLight').sidebar}\") : (darkMode ? \"${colors('dark').sidebar}\" : \"${colors('light').sidebar}\")\n    readonly property color surface: highContrast ? (darkMode ? \"${colors('highContrastDark').surface}\" : \"${colors('highContrastLight').surface}\") : (darkMode ? \"${colors('dark').surface}\" : \"${colors('light').surface}\")\n    readonly property color surfaceHover: highContrast ? (darkMode ? \"${colors('highContrastDark').surfaceHover}\" : \"${colors('highContrastLight').surfaceHover}\") : (darkMode ? \"${colors('dark').surfaceHover}\" : \"${colors('light').surfaceHover}\")\n    readonly property color surfaceSelected: highContrast ? (darkMode ? \"${colors('highContrastDark').surfaceSelected}\" : \"${colors('highContrastLight').surfaceSelected}\") : (darkMode ? \"${colors('dark').surfaceSelected}\" : \"${colors('light').surfaceSelected}\")\n    readonly property color surfaceRaised: highContrast ? (darkMode ? \"${colors('highContrastDark').surfaceRaised}\" : \"${colors('highContrastLight').surfaceRaised}\") : (darkMode ? \"${colors('dark').surfaceRaised}\" : \"${colors('light').surfaceRaised}\")\n    readonly property color border: highContrast ? (darkMode ? \"${colors('highContrastDark').border}\" : \"${colors('highContrastLight').border}\") : (darkMode ? \"${colors('dark').border}\" : \"${colors('light').border}\")\n    readonly property color borderStrong: highContrast ? (darkMode ? \"${colors('highContrastDark').borderStrong}\" : \"${colors('highContrastLight').borderStrong}\") : (darkMode ? \"${colors('dark').borderStrong}\" : \"${colors('light').borderStrong}\")\n    readonly property color textPrimary: highContrast ? (darkMode ? \"${colors('highContrastDark').textPrimary}\" : \"${colors('highContrastLight').textPrimary}\") : (darkMode ? \"${colors('dark').textPrimary}\" : \"${colors('light').textPrimary}\")\n    readonly property color textSecondary: highContrast ? (darkMode ? \"${colors('highContrastDark').textSecondary}\" : \"${colors('highContrastLight').textSecondary}\") : (darkMode ? \"${colors('dark').textSecondary}\" : \"${colors('light').textSecondary}\")\n    readonly property color textMuted: highContrast ? (darkMode ? \"${colors('highContrastDark').textMuted}\" : \"${colors('highContrastLight').textMuted}\") : (darkMode ? \"${colors('dark').textMuted}\" : \"${colors('light').textMuted}\")\n    readonly property color accent: highContrast ? (darkMode ? \"${colors('highContrastDark').accent}\" : \"${colors('highContrastLight').accent}\") : accentBase\n    readonly property color accentMuted: highContrast ? (darkMode ? \"${colors('highContrastDark').accentMuted}\" : \"${colors('highContrastLight').accentMuted}\") : (darkMode ? \"${colors('dark').accentMuted}\" : \"${colors('light').accentMuted}\")\n    readonly property color success: highContrast ? (darkMode ? \"${colors('highContrastDark').success}\" : \"${colors('highContrastLight').success}\") : (darkMode ? \"${colors('dark').success}\" : \"${colors('light').success}\")\n    readonly property color warning: highContrast ? (darkMode ? \"${colors('highContrastDark').warning}\" : \"${colors('highContrastLight').warning}\") : (darkMode ? \"${colors('dark').warning}\" : \"${colors('light').warning}\")\n    readonly property color danger: highContrast ? (darkMode ? \"${colors('highContrastDark').danger}\" : \"${colors('highContrastLight').danger}\") : (darkMode ? \"${colors('dark').danger}\" : \"${colors('light').danger}\")\n    readonly property color info: highContrast ? (darkMode ? \"${colors('highContrastDark').info}\" : \"${colors('highContrastLight').info}\") : (darkMode ? \"${colors('dark').info}\" : \"${colors('light').info}\")\n    readonly property color focusRing: accent\n\n    readonly property int radiusSmall: ${source.radiusDp.extraSmall}\n    readonly property int radiusMedium: ${source.radiusDp.small}\n    readonly property int radiusLarge: ${source.radiusDp.medium}\n    readonly property int titleBarHeight: Math.round(${layout.titleBarHeight} * Math.max(1.0, fontScale))\n    readonly property int navigationCollapsedWidth: Math.round(${layout.navigationCollapsedWidth} * Math.max(1.0, fontScale))\n    readonly property int navigationExpandedWidth: Math.round(${layout.navigationExpandedWidth} * Math.max(1.0, fontScale))\n    readonly property int detailsWidth: Math.round(${layout.detailsWidth} * Math.max(1.0, fontScale))\n    readonly property int customizationWidth: Math.round(${layout.customizationWidth} * Math.max(1.0, fontScale))\n    readonly property int commandHeight: Math.round(${layout.commandHeight} * densityScale * Math.max(1.0, fontScale))\n    readonly property int rowHeight: Math.round(${layout.rowHeight} * densityScale * Math.max(1.0, fontScale))\n    readonly property int spaceScreenHorizontal: ${source.spacingDp.screenHorizontal}\n    readonly property int spaceSection: ${source.spacingDp.section}\n    readonly property int spaceItemGap: ${source.spacingDp.itemGap}\n    readonly property int spaceCompactGap: ${source.spacingDp.compactGap}\n\n    readonly property int fontTiny: Math.round(${source.typographySp.fontTiny} * fontScale)\n    readonly property int fontSmall: Math.round(${source.typographySp.fontSmall} * fontScale)\n    readonly property int fontBody: Math.round(${source.typographySp.fontBody} * fontScale)\n    readonly property int fontMedium: Math.round(${source.typographySp.fontMedium} * fontScale)\n    readonly property int fontTitle: Math.round(${source.typographySp.fontTitle} * fontScale)\n\n    readonly property int animationFast: reducedMotion ? 0 : ${source.motionMs.fast}\n    readonly property int animationNormal: reducedMotion ? 0 : ${source.motionMs.normal}\n}\n`;
}

function generateKotlin(source) {
  const lines = [
    '// Generated by scripts/generate-design-tokens.mjs from nova-design-tokens.json.',
    'package com.nova.downloadmanager.design',
    '',
    'import androidx.compose.ui.unit.dp',
    'import androidx.compose.ui.unit.sp',
    '',
    'object NOVADesignTokens {',
  ];
  for (const [paletteName, palette] of Object.entries(source.palettes)) {
    for (const [name, color] of Object.entries(palette)) {
      lines.push(`    const val ${pascal(paletteName)}${pascal(name)}: Long = ${kotlinColor(color)}`);
    }
  }
  lines.push('');
  for (const [name, value] of Object.entries(source.spacingDp)) {
    lines.push(`    val ${pascal(name)} = ${value}.dp`);
  }
  for (const [name, value] of Object.entries(source.radiusDp)) {
    lines.push(`    val Radius${pascal(name)} = ${value}.dp`);
  }
  for (const [name, value] of Object.entries(source.typographySp)) {
    const tokenName = name.startsWith('font') ? pascal(name) : `Font${pascal(name)}`;
    lines.push(`    val ${tokenName} = ${value}.sp`);
  }
  for (const [name, value] of Object.entries(source.motionMs)) {
    lines.push(`    const val Motion${pascal(name)}Millis: Int = ${value}`);
  }
  lines.push('');
  lines.push('    object IconSemantics {');
  for (const semantic of source.iconSemantics) {
    lines.push(`        const val ${pascal(semantic)}: String = ${JSON.stringify(semantic)}`);
  }
  lines.push('    }');
  lines.push('}');
  return `${lines.join('\n')}\n`;
}

function pascal(value) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function kotlinColor(hex) {
  const normalized = hex.replace('#', '');
  const argb = normalized.length === 6 ? `FF${normalized}` : normalized;
  return `0x${argb.toUpperCase()}L`;
}
